// Guardián del Vigía (17-nov): el Vigía revisa a los demás flujos, pero si él deja de correr
// (apagado, disparador trabado o fallando seguido) nadie se enteraba. Esto lo revisa cada hora.
// Límite conocido: si se cae n8n entero, este guardián tampoco corre (para eso hace falta un monitor externo).
const VIGILADO = 'zTm4tMOV9vMfUDnG';
const MAX_MIN_SIN_CORRER = 150;   // el Vigía corre cada 2 h
const REAVISO_HORAS = 6;
const wf = $('🔎 n8n: Estado del Vigía').first().json;
const ex = ($('🔎 n8n: Últimas corridas del Vigía').first().json.data || []);
const ahora = Date.now();
const problemas = [];
if (wf.error || !wf.id) problemas.push('No se pudo leer el flujo del Vigía en n8n: ' + (wf.error?.message || wf.message || 'sin respuesta'));
else if (!wf.active) problemas.push('El Vigía está APAGADO en n8n.');
const ok = ex.filter(e => e.status === 'success');
const ultimaOk = ok.length ? new Date(ok[0].startedAt).getTime() : 0;
const minSinOk = ultimaOk ? Math.round((ahora - ultimaOk) / 60000) : null;
if (wf.id && wf.active) {
  if (!ultimaOk) problemas.push('No hay ninguna corrida exitosa reciente del Vigía.');
  else if (minSinOk > MAX_MIN_SIN_CORRER) problemas.push(`La última corrida exitosa del Vigía fue hace ${Math.floor(minSinOk / 60)} h ${minSinOk % 60} min (debería correr cada 2 h).`);
  const ultimas = ex.slice(0, 2);
  if (ultimas.length === 2 && ultimas.every(e => e.status === 'error')) problemas.push('Las 2 últimas corridas del Vigía terminaron con error.');
}
const st = $getWorkflowStaticData('global');
let enviar = false, asunto = '', texto = '';
if (problemas.length) {
  const ultimoAviso = st.ultimoAviso || 0;
  if (ahora - ultimoAviso > REAVISO_HORAS * 3600000) {
    enviar = true; st.ultimoAviso = ahora; st.enFalla = true;
    asunto = '🛡️ G54: el Vigía no está funcionando';
    texto = 'El guardián del Vigía encontró:\n\n- ' + problemas.join('\n- ') +
      '\n\nMientras tanto nadie revisa posts atascados, contenido cruzado ni flujos caídos.\nRevisar en n8n el flujo ' + VIGILADO + '.\n(Este aviso se repite cada ' + REAVISO_HORAS + ' h mientras siga igual.)';
  }
} else if (st.enFalla) {
  enviar = true; st.enFalla = false; st.ultimoAviso = 0;
  asunto = '🛡️ G54: el Vigía volvió a funcionar';
  texto = 'El Vigía volvió a correr bien. Última corrida exitosa: hace ' + minSinOk + ' min.';
}
return [{ json: { enviar, asunto, texto, problemas, minSinOk, vigilado: VIGILADO } }];
